A two-column grid (the recipe for `numColumns`: virtualize rows of N items)
```tsx
"use client";
import { useVirtualList } from "denext";

export function Grid({ photos }: { photos: { id: string; src: string }[] }) {
  const columns = 2;
  const rows = Math.ceil(photos.length / columns);
  const list = useVirtualList({ count: rows, getItem: (r) => r, estimatedItemSize: 180 });
  return (
    <div {...list.scrollProps} style={{ ...list.scrollProps.style, height: "100vh" }}>
      <div {...list.innerProps}>
        {list.items.map((row) => (
          <div
            key={row.key}
            ref={row.measureRef}
            style={{
              position: "absolute", top: 0, left: 0, right: 0,
              transform: `translateY(${row.offset}px)`,
              display: "grid", gridTemplateColumns: `repeat(${columns}, 1fr)`, gap: "8px",
            }}
          >
            {photos.slice(row.index * columns, row.index * columns + columns).map((p) => (
              <img key={p.id} src={p.src} />
            ))}
          </div>
        ))}
      </div>
    </div>
  );
}
```

```tsx
"use client";
import { useRef, useVirtualReorder, VirtualList, type VirtualListHandle } from "denext";

export function Playlist({ songs, move }) {
  const list = useRef<VirtualListHandle>(null);
  const reorder = useVirtualReorder({ list, count: songs.length, onReorder: move });
  return (
    <>
      <VirtualList
        ref={list}
        data={songs}
        keepMounted={reorder.keepMounted}
        style={{ height: 480 }}
        renderItem={(s, i) => (
          <div {...reorder.itemProps(i)}>
            <button {...reorder.handleProps(i)} aria-label={`Move ${s.title}`}>⠿</button>
            {s.title}
          </div>
        )}
      />
      {reorder.liveRegion}
    </>
  );
}
```

